#include <stdio.h>

int main(void) {
    long long rows, columns;
    scanf("%lld%lld", &rows, &columns);
    long long answer;
    if (rows == 1 || columns == 1) {
        answer = rows * columns;
    } else {
        answer = 2 * rows + 2 * columns - 4;
    }
    printf("%lld\n", answer);
    return 0;
}

